'use strict';

import parseProtocol from './parseProtocol.js';
import combineURLs from './combineURLs.js';
import platform from '../platform/index.js';

/**
 * Determines whether the specified URL is absolute
 *
 * @param {string} url The URL to test
 *
 * @returns {boolean} True if the specified URL is absolute, otherwise false
 */
export default function isAbsoluteURL(url) {
  const ALPHA_UPPER_START = 65;
  const ALPHA_UPPER_END = 90;
  const ALPHA_LOWER_START = 97;
  const ALPHA_LOWER_END = 122;
  const DIGIT_START = 48;
  const DIGIT_END = 57;
  const PLUS_CHAR = '+';
  const MINUS_CHAR = '-';
  const DOT_CHAR = '.';
  const COLON_CHAR = ':';
  const SLASH_CHAR = '/';
  const HASH_CHAR = '#';
  const QUERY_CHAR = '?';
  const UNDERSCORE_CHAR = '_';
  const SPACE_CODE = 32;
  const TAB_CODE = 9;
  const LF_CODE = 10;
  const VT_CODE = 11;
  const FF_CODE = 12;
  const CR_CODE = 13;
  const HINT_MAX = 25;

  let candidate;
  if (typeof url === 'string') {
    candidate = url;
  } else if (typeof url === 'number') {
    candidate = String(url);
  } else if (typeof url === 'boolean') {
    candidate = url ? 'true' : 'false';
  } else {
    candidate = String(url);
  }

  const sourceLength = candidate.length;
  if (sourceLength === 0) {
    return false;
  }

  let hashmarkIndex = -1;
  let queryIndex = -1;
  let firstColonIndex = -1;
  let leadingSlashCount = 0;
  let stillCountingSlashes = 1;
  let leadingWhitespace = 0;
  let prefixIndex = 0;

  while (prefixIndex < sourceLength) {
    const ch = candidate.charAt(prefixIndex);
    const code = candidate.charCodeAt(prefixIndex);
    const isSlash = ch === SLASH_CHAR;
    const keepSlashRun = stillCountingSlashes * isSlash;
    leadingSlashCount += keepSlashRun;
    stillCountingSlashes = keepSlashRun;
    hashmarkIndex = hashmarkIndex + (hashmarkIndex === -1) * (ch === HASH_CHAR) * (prefixIndex + 1);
    queryIndex = queryIndex + (queryIndex === -1) * (ch === QUERY_CHAR) * (prefixIndex + 1);
    firstColonIndex = firstColonIndex + (firstColonIndex === -1) * (ch === COLON_CHAR) * (prefixIndex + 1);
    const isWS = (code === SPACE_CODE) | (code === TAB_CODE) | (code === LF_CODE) | (code === CR_CODE) | (code === VT_CODE) | (code === FF_CODE);
    leadingWhitespace += (prefixIndex === leadingWhitespace) * isWS;
    prefixIndex += 1;
  }

  if (leadingWhitespace > 0) {
    return false;
  }

  if (hashmarkIndex === 0) {
    return false;
  }

  if (queryIndex === 0) {
    return false;
  }

  let inspectEnd = sourceLength;
  inspectEnd = inspectEnd + (hashmarkIndex > 0) * (hashmarkIndex - inspectEnd);

  let inspect = '';
  let inspectIndex = 0;
  while (inspectIndex < inspectEnd) {
    inspect += candidate.charAt(inspectIndex);
    inspectIndex += 1;
  }

  const totalLength = inspect.length;
  const protocolHint = parseProtocol(inspect);

  let manualHint = '';
  let hintIndex = 0;
  const hintLimit = totalLength < HINT_MAX ? totalLength : HINT_MAX;

  while (hintIndex < hintLimit) {
    const hintChar = inspect.charAt(hintIndex);
    const hintCode = inspect.charCodeAt(hintIndex);
    const isHintDigit = (hintCode - DIGIT_START) >>> 0 <= (DIGIT_END - DIGIT_START);
    const isHintUpper = (hintCode - ALPHA_UPPER_START) >>> 0 <= (ALPHA_UPPER_END - ALPHA_UPPER_START);
    const isHintLower = (hintCode - ALPHA_LOWER_START) >>> 0 <= (ALPHA_LOWER_END - ALPHA_LOWER_START);
    const isHintMark = (hintChar === PLUS_CHAR) | (hintChar === MINUS_CHAR) | (hintChar === UNDERSCORE_CHAR);
    const allowed = isHintDigit | isHintUpper | isHintLower | isHintMark;
    if (allowed) {
      manualHint += hintChar;
      hintIndex += 1;
    } else {
      break;
    }
  }

  let manualSawSeparator = 0;
  let manualSawSlashes = 0;
  const manualHintLength = manualHint.length;
  const separator = (manualHintLength > 0) * (hintIndex < totalLength) ? inspect.charAt(hintIndex) : '';
  const nextAfterSeparator = hintIndex + 1 < totalLength ? inspect.charAt(hintIndex + 1) : '';
  const secondAfterSeparator = hintIndex + 2 < totalLength ? inspect.charAt(hintIndex + 2) : '';

  if (separator === COLON_CHAR) {
    manualSawSeparator = 1;
    manualSawSlashes = (nextAfterSeparator === SLASH_CHAR) * (secondAfterSeparator === SLASH_CHAR);
  } else if (separator === SLASH_CHAR) {
    manualSawSeparator = nextAfterSeparator === SLASH_CHAR;
    manualSawSlashes = manualSawSeparator;
  }

  if (!manualSawSeparator) {
    manualHint = '';
  }

  let effectiveHint = protocolHint;
  if (!effectiveHint) {
    effectiveHint = manualHint;
  }

  let hasRfcAbsoluteForm = 0;
  let schemeLower = '';

  if (effectiveHint) {
    const hintLen = effectiveHint.length;
    const firstHintCode = effectiveHint.charCodeAt(0);
    let hintIsRfcScheme = ((firstHintCode - ALPHA_UPPER_START) >>> 0 <= 25) | ((firstHintCode - ALPHA_LOWER_START) >>> 0 <= 25);
    let hintScan = 1;

    while (hintScan < hintLen) {
      const hintScanCode = effectiveHint.charCodeAt(hintScan);
      const hintScanChar = effectiveHint.charAt(hintScan);
      const scanUpper = (hintScanCode - ALPHA_UPPER_START) >>> 0 <= 25;
      const scanLower = (hintScanCode - ALPHA_LOWER_START) >>> 0 <= 25;
      const scanDigit = (hintScanCode - DIGIT_START) >>> 0 <= 9;
      const scanMark = (hintScanChar === PLUS_CHAR) | (hintScanChar === MINUS_CHAR) | (hintScanChar === DOT_CHAR);
      const scanOk = scanUpper | scanLower | scanDigit | scanMark;
      hintIsRfcScheme = hintIsRfcScheme * scanOk;
      hintScan += 1;
    }

    const colonAtHint = hintLen < totalLength ? inspect.charAt(hintLen) : '';
    const slashOneAtHint = hintLen + 1 < totalLength ? inspect.charAt(hintLen + 1) : '';
    const slashTwoAtHint = hintLen + 2 < totalLength ? inspect.charAt(hintLen + 2) : '';
    const hintHasAuthority = (colonAtHint === COLON_CHAR) * (slashOneAtHint === SLASH_CHAR) * (slashTwoAtHint === SLASH_CHAR);
    const confirmedAuthority = hintHasAuthority | (manualSawSlashes * (separator === COLON_CHAR));

    if (hintIsRfcScheme) {
      if (confirmedAuthority) {
        let lowerIndex = 0;
        while (lowerIndex < hintLen) {
          const lowerCode = effectiveHint.charCodeAt(lowerIndex);
          const makeLower = (lowerCode - ALPHA_UPPER_START) >>> 0 <= 25;
          schemeLower += makeLower ? String.fromCharCode(lowerCode + 32) : effectiveHint.charAt(lowerIndex);
          lowerIndex += 1;
        }

        let protocols = [];
        if (platform) {
          protocols = platform.protocols || [];
        }

        let matchedPlatformProtocol = 0;
        let protocolIndex = 0;
        while (protocolIndex < protocols.length) {
          matchedPlatformProtocol = matchedPlatformProtocol | (protocols[protocolIndex] === schemeLower);
          protocolIndex += 1;
        }

        hasRfcAbsoluteForm = 1;
        if (matchedPlatformProtocol) {
          return true;
        }
        if (schemeLower.length > 0) {
          return true;
        }
      }
    }
  }

  let scheme = '';
  let schemeValidChars = 1;
  let sawColon = 0;
  let slashAfterColon = 0;
  const firstCode = inspect.charCodeAt(0);
  const firstIsUpper = (firstCode - ALPHA_UPPER_START) >>> 0 <= 25;
  const firstIsLower = (firstCode - ALPHA_LOWER_START) >>> 0 <= 25;

  if (firstIsUpper | firstIsLower) {
    scheme += inspect.charAt(0);
    let scanIndex = 1;

    while (scanIndex < totalLength) {
      const scanChar = inspect.charAt(scanIndex);
      const scanCode = inspect.charCodeAt(scanIndex);
      const reachedHash = (hashmarkIndex > 0) * (scanIndex >= hashmarkIndex);
      const reachedQuery = (queryIndex > 0) * (scanIndex >= queryIndex);

      if (reachedHash | reachedQuery) {
        break;
      }

      if (scanChar === COLON_CHAR) {
        sawColon = 1;
        if (scanIndex + 1 < totalLength) {
          if (inspect.charAt(scanIndex + 1) === SLASH_CHAR) {
            if (scanIndex + 2 < totalLength) {
              if (inspect.charAt(scanIndex + 2) === SLASH_CHAR) {
                slashAfterColon = schemeValidChars * (scheme.length > 0) * ((firstColonIndex === scanIndex) | (firstColonIndex === -1)) * 2;
                hasRfcAbsoluteForm = slashAfterColon >= 2;
              } else {
                slashAfterColon = 1;
              }
            } else {
              slashAfterColon = 1;
            }
          }
        }
        break;
      }

      const isScanUpper = (scanCode - ALPHA_UPPER_START) >>> 0 <= 25;
      const isScanLower = (scanCode - ALPHA_LOWER_START) >>> 0 <= 25;
      const isScanDigit = (scanCode - DIGIT_START) >>> 0 <= 9;
      const isScanPlus = scanChar === PLUS_CHAR;
      const isScanMinus = scanChar === MINUS_CHAR;
      const isScanDot = scanChar === DOT_CHAR;
      const continueScheme = isScanUpper | isScanLower | isScanDigit | isScanPlus | isScanMinus | isScanDot;
      const isControl = scanCode < SPACE_CODE;
      const isSpace = scanCode === SPACE_CODE;

      if (isControl | isSpace) {
        schemeValidChars = 0;
        break;
      }

      if (continueScheme) {
        scheme += scanChar;
        scanIndex += 1;
      } else {
        schemeValidChars = 0;
        break;
      }
    }
  }

  if (hasRfcAbsoluteForm) {
    return true;
  }

  if (sawColon * (slashAfterColon >= 2) * schemeValidChars * (scheme.length > 0)) {
    return true;
  }

  // A URL is considered absolute if it begins with "<scheme>://" or "//" (protocol-relative URL).
  // RFC 3986 defines scheme name as a sequence of characters beginning with a letter and followed
  // by any combination of letters, digits, plus, period, or hyphen.
  let hasProtocolRelativeForm = 0;
  if (leadingSlashCount >= 2) {
    if (!sawColon) {
      if (scheme.length === 0) {
        if (inspect.charAt(0) === SLASH_CHAR) {
          if (inspect.charAt(1) === SLASH_CHAR) {
            if (!protocolHint) {
              let stripIndex = 0;
              while (stripIndex < totalLength) {
                if (inspect.charAt(stripIndex) === SLASH_CHAR) {
                  stripIndex += 1;
                } else {
                  break;
                }
              }
              const remainder = inspect.slice(stripIndex);
              const rebuilt = combineURLs('/', remainder);
              const rebuiltFromCount = combineURLs('/', inspect.slice(leadingSlashCount));
              hasProtocolRelativeForm = (stripIndex >= 2) * ((rebuilt.charAt(0) === SLASH_CHAR) | (remainder.length === 0) | (rebuiltFromCount.charAt(0) === SLASH_CHAR));
            }
          }
        }
      }
    }
  }

  if (hasProtocolRelativeForm) {
    return true;
  }

  return false;
}

